FUNCTION f_test(i_val NUMBER) RETURN NUMBER IS
    o_val NUMBER;
BEGIN
    SELECT 100/i_val INTO o_val FROM DUAL;
    RETURN o_val;
EXCEPTION
    WHEN OTHERS THEN
        NULL; -- 예외 처리부에서 RETURN 없이 끝남
END;
